<?php
declare(strict_types=1);
use Moves\Services\Csrf; use Moves\Services\Helpdesk; use Moves\Services\HelpdeskNotifier; use Moves\Services\SessionAuth; use Moves\Support\CmsView as V;
$userId = (int) SessionAuth::current()['id'];
$ticket = preg_match('/^RZ-\d{6,}$/', $protocol) === 1 ? Helpdesk::customerTicket($userId, $protocol) : null;
require dirname(__DIR__) . '/components/support-shell.php';
if ($ticket === null) { http_response_code(404); $supportOpen('Chamado não encontrado'); echo '<section class="sp-card"><p>Este chamado não existe ou você não tem acesso a ele.</p></section>'; $supportClose(); return; }
HelpdeskNotifier::markTicketRead($userId, 'customer', (int) $ticket['id']);
$token = '<input type="hidden" name="csrf_token" value="' . V::e(Csrf::token()) . '">'; $base = '/suporte/' . V::e($ticket['protocol']); $s = $ticket['status'];
$eventText = static function (array $e): string { if ($e['event_type'] === 'created') { return 'Chamado aberto'; } if ($e['event_type'] === 'reopened') { return 'Chamado reaberto'; } return 'Situação: ' . (V::TICKET_STATUS[$e['to_value']] ?? $e['to_value']); };
$supportOpen($ticket['subject']); ?>
<section class="sp-card"><p class="sp-meta"><strong><?= V::e($ticket['protocol']) ?></strong> · <em class="sp-status sp-status-<?= V::e($s) ?>"><?= V::e(V::TICKET_STATUS[$s] ?? $s) ?></em> · <?= V::e($ticket['category_name']) ?> · Prioridade <?= V::e(V::PRIORITIES[$ticket['priority']] ?? '') ?> · <?= V::e($ticket['organization_name'] ?? 'Pessoal') ?></p>
<div class="sp-timeline"><?php foreach (Helpdesk::timeline((int) $ticket['id'], false) as $item): if ($item['kind'] === 'event'): ?><p class="sp-event"><?= V::e($eventText($item)) ?> · <?= V::date($item['created_at']) ?></p><?php else: ?><article class="sp-msg<?= $item['author_type'] === 'staff' ? ' sp-msg-staff' : '' ?>"><header><strong><?= V::e($item['author_name'] ?? '') ?></strong><time><?= V::date($item['created_at']) ?></time></header><p><?= V::e($item['body']) ?></p><?php foreach ($item['attachments'] as $file): ?><a class="sp-file" href="/suporte/anexo/<?= (int) $file['id'] ?>"><?= V::e($file['original_name']) ?> (<?= V::size((int) $file['size_bytes']) ?>)</a><?php endforeach; ?></article><?php endif; endforeach; ?></div></section>
<?php if ($s !== 'closed'): ?><section class="sp-card"><h2><?= $s === 'resolved' ? 'Ainda precisa de ajuda?' : 'Responder' ?></h2><form class="sp-form" method="post" action="<?= $base ?>/responder" enctype="multipart/form-data"><?= $token ?><label for="sp-reply">Mensagem</label><textarea id="sp-reply" name="body" rows="4" required maxlength="10000"></textarea><label for="sp-reply-files">Anexar arquivos</label><input id="sp-reply-files" type="file" name="attachments[]" multiple accept=".jpg,.jpeg,.png,.gif,.webp,.pdf,.txt"><button class="sp-btn sp-btn-primary">Enviar</button></form></section><?php endif; ?>
<section class="sp-actions"><?php if (!in_array($s, ['resolved', 'closed'], true)): ?><form method="post" action="<?= $base ?>/resolver"><?= $token ?><button class="sp-btn">Marcar como resolvido</button></form><?php endif; ?><?php if ($s === 'resolved'): ?><form method="post" action="<?= $base ?>/confirmar"><?= $token ?><button class="sp-btn sp-btn-primary">Confirmar resolução e encerrar</button></form><form method="post" action="<?= $base ?>/reabrir"><?= $token ?><button class="sp-btn">Reabrir</button></form><?php endif; ?></section>
<?php if (in_array($s, ['resolved', 'closed'], true)): ?><section class="sp-card"><h2>Avaliação do atendimento</h2><?php if ($ticket['rating']): ?><p>Sua avaliação: <strong><?= V::e(V::RATINGS[$ticket['rating']] ?? '') ?></strong><?= $ticket['rating_comment'] !== '' ? ' · ' . V::e($ticket['rating_comment']) : '' ?></p><?php else: ?><form class="sp-form" method="post" action="<?= $base ?>/avaliar"><?= $token ?><fieldset class="sp-rating"><legend>Como foi o atendimento?</legend><?php foreach (V::RATINGS as $key => $label): ?><label><input type="radio" name="rating" value="<?= V::e($key) ?>" required> <?= V::e($label) ?></label><?php endforeach; ?></fieldset><label for="sp-rate-comment">Comentário (opcional)</label><textarea id="sp-rate-comment" name="comment" rows="2" maxlength="500"></textarea><button class="sp-btn">Enviar avaliação</button></form><?php endif; ?></section><?php endif; ?>
<?php $supportClose();
